var APY=Object.assign(window.APY||{},{"“读万卷书，行万里路”的意思是：":"“Dú wàn juàn shū, xíng wàn lǐ lù” de yìsi shì:","下一趟":"Xià yí tàng","买东西":"Mǎi dōngxi","买张无座票":"Mǎi zhāng wú zuò piào","了解中国":"Liǎojiě Zhōngguó","了解历史文化":"Liǎojiě lìshǐ wénhuà","了解如何在中国旅行，体验中国文化。":"Liǎojiě rúhé zài Zhōngguó lǚxíng, tǐyàn Zhōngguó wénhuà.","了解旅行过程":"Liǎojiě lǚxíng guòchéng","交到朋友":"Jiāodào péngyou","仔细检查行李":"Zǐxì jiǎnchá xíngli","他们这次去西双版纳要做什么？":"Tāmen zhè cì qù Xīshuāngbǎnnà yào zuò shénme?","你买的":"Nǐ mǎi de","你们要是":"Nǐmen yàoshi","你喜欢旅行吗？如果喜欢，你喜欢去看自然景色还是去历史文化景点？":"Nǐ xǐhuan lǚxíng ma? Rúguǒ xǐhuan, nǐ xǐhuan qù kàn zìrán jǐngsè háishi qù lìshǐ wénhuà jǐngdiǎn?","做好旅行计划":"Zuò hǎo lǚxíng jìhuà","列":"Liè","动车车速也挺快啊！对了，这列车晚上七点多到杭州，咱们在车上吃晚餐，到站后就先去西湖吧，夜里的西湖更美。":"Dòngchē chēsù yě tǐng kuài a! Duì le, zhè liè chē wǎnshang qī diǎn duō dào Hángzhōu, zánmen zài chē shang chī wǎncān, dào zhàn hòu jiù xiān qù Xī Hú ba, yè li de Xī Hú gèng měi.","去看":"Qù kàn","去西安的旅客开始登机，请拿好登机牌按顺序排队。":"Qù Xī'ān de lǚkè kāishǐ dēngjī, qǐng náhǎo dēngjīpái àn shùnxù páiduì.","去西湖方便":"Qù Xī Hú fāngbiàn","参加比赛":"Cānjiā bǐsài","只通过":"Zhǐ tōngguò","吃美食":"Chī měishí","吗":"Ma","听中文歌":"Tīng Zhōngwén gē","听演唱会":"Tīng yǎnchànghuì","嗯。中国太大了！真是看也看不完啊。":"Ǹg. Zhōngguó tài dà le! Zhēn shì kàn yě kàn bu wán a.","在机场，李文和白家月、安妮、陈天中安检后准备登机去西双版纳，他们先在西安转机。":"Zài jīchǎng, Lǐ Wén hé Bái Jiāyuè, Ānnī, Chén Tiānzhōng ānjiǎn hòu zhǔnbèi dēngjī qù Xīshuāngbǎnnà, tāmen xiān zài Xī'ān zhuǎnjī.","坐下一趟车":"Zuòxià yí tàng chē","堵车":"Dǔchē","好！后天我们坐大巴去苏州，看苏州园林。":"Hǎo! Hòutiān wǒmen zuò dàbā qù Sūzhōu, kàn Sūzhōu yuánlín.","如果安妮没有坐上车，白家月有什么建议？":"Rúguǒ Ānnī méiyǒu zuò shang chē, Bái Jiāyuè yǒu shénme jiànyì?","安妮为什么建议下车后就去西湖？":"Ānnī wèi shénme jiànyì xià chē hòu jiù qù Xī Hú?","安检":"Ānjiǎn","安检完后，白家月、陈天中和安妮都在干什么？":"Ānjiǎn wán hòu, Bái Jiāyuè, Chén Tiānzhōng hé Ānnī dōu zài gàn shénme?","安检完就等着登机了。你们在看什么？":"Ānjiǎn wán jiù děngzhe dēngjī le. Nǐmen zài kàn shénme?","导游":"Dǎoyóu","就不能":"Jiù bù néng","应该不是。很多人的目的地是西安，你别忘了，咱们是在西安转机，然后再飞西双版纳。":"Yīnggāi bú shì. Hěn duō rén de mùdìdì shì Xī'ān, nǐ bié wàng le, zánmen shì zài Xī'ān zhuǎnjī, ránhòu zài fēi Xīshuāngbǎnnà.","怎么能":"Zěnme néng","总结":"Zǒngjié","想多了解中国":"Xiǎng duō liǎojiě Zhōngguó","意见":"Yìjiàn","感受泼水节":"Gǎnshòu Pōshuǐjié","我在最外边。这么多人，是不是跟咱们一样，都是去感受泼水节的啊？":"Wǒ zài zuì wàibian. Zhème duō rén, shì bu shì gēn zánmen yíyàng, dōu shì qù gǎnshòu Pōshuǐjié de a?","我在读老舍的小说。":"Wǒ zài dú Lǎo Shě de xiǎoshuō.","我很喜欢旅行。我更喜欢去看自然景色，比如下龙湾、沙坝，看到美丽的大山大海，心情特别放松。":"Wǒ hěn xǐhuan lǚxíng. Wǒ gèng xǐhuan qù kàn zìrán jǐngsè, bǐrú Xiàlóng Wān, Shābà, kàndào měilì de dà shān dà hǎi, xīnqíng tèbié fàngsōng.","我是坐……去的，……":"Wǒ shì zuò …… qù de, ……","我的座位就在前边，我想先站这儿跟你们说说话。":"Wǒ de zuòwèi jiù zài qiánbian, wǒ xiǎng xiān zhàn zhèr gēn nǐmen shuōshuo huà.","我读唐诗呢。几千年的中国文化，真是读也读不完。":"Wǒ dú Tángshī ne. Jǐ qiān nián de Zhōngguó wénhuà, zhēn shì dú yě dú bu wán.","我读的是一本中国历史书。":"Wǒ dú de shì yì běn Zhōngguó lìshǐ shū.","所有":"Suǒyǒu","提前订好酒店":"Tíqián dìng hǎo jiǔdiàn","提前订好门票":"Tíqián dìng hǎo ménpiào","改乘":"Gǎi chéng","改坐飞机":"Gǎi zuò fēijī","放松心情":"Fàngsōng xīnqíng","旅客":"Lǚkè","旅行时，你一般会坐火车还是坐飞机？为什么？":"Lǚxíng shí, nǐ yìbān huì zuò huǒchē háishi zuò fēijī? Wèi shénme?","旅行经验谈":"Lǚxíng jīngyàn tán","无座票":"Wú zuò piào","既学习也运动":"Jì xuéxí yě yùndòng","既读书学习，也外出看世界":"Jì dú shū xuéxí, yě wàichū kàn shìjiè","明天再去":"Míngtiān zài qù","是":"Shì","晚上西湖更好看":"Wǎnshang Xī Hú gèng hǎokàn","晚了":"Wǎnle","晚餐":"Wǎncān","更多的地方":"Gèng duō de dìfang","查到":"Chádào","根据课文，旅行除了能看自然景色外，还能：":"Gēnjù kèwén, lǚxíng chúle néng kàn zìrán jǐngsè wài, hái néng:","没关系，晚了就改乘下一趟。天中，你坐哪儿？看你一直不坐下，我还在想，难道你买的是无座票吗？":"Méi guānxi, wǎnle jiù gǎi chéng xià yí tàng. Tiānzhōng, nǐ zuò nǎr? Kàn nǐ yìzhí bú zuòxia, wǒ hái zài xiǎng, nándào nǐ mǎi de shì wú zuò piào ma?","流利":"Liúlì","点儿吧":"Diǎnr ba","烦恼":"Fánnǎo","特点":"Tèdiǎn","登机":"Dēngjī","白家月、安妮和陈天中坐动车去杭州、苏州游玩。":"Bái Jiāyuè, Ānnī hé Chén Tiānzhōng zuò dòngchē qù Hángzhōu, Sūzhōu yóuwán.","白家月、安妮和陈天中想通过旅行：":"Bái Jiāyuè, Ānnī hé Chén Tiānzhōng xiǎng tōngguò lǚxíng:","白家月、安妮和陈天中的旅行经验首先是：":"Bái Jiāyuè, Ānnī hé Chén Tiānzhōng de lǚxíng jīngyàn shǒuxiān shì:","百分之":"Bǎi fēn zhī","看书":"Kàn shū","看电影":"Kàn diànyǐng","积累知识":"Jīlěi zhīshi","第一/第二/第三":"Dì-yī / dì-èr / dì-sān","累就累":"Lèi jiù lèi","红包":"Hóngbāo","终于上来了，我的座位靠窗户。":"Zhōngyú shànglai le, wǒ de zuòwèi kào chuānghu.","终于上车了，刚刚路上堵车，差点儿晚了。":"Zhōngyú shàng chē le, gānggāng lùshang dǔchē, chàdiǎnr wǎn le.","给我留下印象最深的一个景点":"Gěi wǒ liúxia yìnxiàng zuì shēn de yí ge jǐngdiǎn","给我留下印象最深的地方是……":"Gěi wǒ liúxia yìnxiàng zuì shēn de dìfang shì ……","能够口头或书面表达某一景点的特色。":"Nénggòu kǒutóu huò shūmiàn biǎodá mǒu yì jǐngdiǎn de tèsè.","能够听懂并交流关于读书与旅行的话题。":"Nénggòu tīngdǒng bìng jiāoliú guānyú dú shū yǔ lǚxíng dehuàtí.","航班":"Hángbān","节省":"Jiéshěng","花更少的钱":"Huā gèng shǎo de qián","西湖不要门票":"Xī Hú bú yào ménpiào","西湖离得近":"Xī Hú lí de jìn","要是":"Yàoshi","要是……，就……，否则……":"Yàoshi ……, jiù ……, fǒuzé ……","要是你去的话，……，否则……":"Yàoshi nǐ qù dehuà, ……, fǒuzé ……","要是路远，我一般坐飞机，因为能节省时间；要是路近，我就坐火车，可以一边坐车一边看风景。":"Yàoshi lù yuǎn, wǒ yìbān zuò fēijī, yīnwèi néng jiéshěng shíjiān; yàoshi lù jìn, wǒ jiù zuò huǒchē, kěyǐ yìbiān zuò chē yìbiān kàn fēngjǐng.","解释":"Jiěshì","计划/航班/转机/安检/节省":"Jìhuà / hángbān / zhuǎnjī / ānjiǎn / jiéshěng","认识朋友":"Rènshi péngyou","读一万本书，走一万里路":"Dú yíwàn běn shū, zǒu yíwàn lǐ lù","读万卷书，行万里路":"Dú wàn juàn shū, xíng wàn lǐ lù","读书":"Dú shū","谁说……呢":"Shéi shuō …… ne","谁说不是呢？不过，现在咱们得去排队，航班的值机员在叫大家登机呢——":"Shéi shuō bú shì ne? Búguò, xiànzài zánmen děi qù páiduì, hángbān de zhíjīyuán zài jiào dàjiā dēngjī ne ——","转机":"Zhuǎnjī","边看书边走路":"Biān kàn shū biān zǒulù","这些信息啊":"Zhèxiē xìnxī a","远距离旅行小贴士":"Yuǎn jùlí lǚxíng xiǎo tiēshì","连手机都没有":"Lián shǒujī dōu méiyǒu","那里的特点是……":"Nàli de tèdiǎn shì ……","难道":"Nándào","难道……吗":"Nándào …… ma","靠":"Kào"});
